{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "The closest structural analogue, a pyrazolopyrimidinone bearing an ethoxy-pyridinesulfonyl piperazine, had absolute oral bioavailability of 34% in healthy volunteers, directly supporting F≥20% for the query's sulfonyl-piperazine fused lactam core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Sildenafil, which shares the sulfonyl piperazine and fused pyrimidinone lactam motif, has an absolute oral bioavailability of about 40% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, a lipophilic basic-amine lactam, had an absolute oral bioavailability of 59% in fed volunteers, supporting high F for a similarly ionizable lactam-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Niraparib, an amide/lactam with a basic piperidine, had an absolute oral bioavailability of 72.7% in cancer patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Thalidomide, a heterocyclic imide/lactam, showed probably high oral bioavailability of 80–100% in fasting volunteers, supporting high F for the query's lactam-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fenspiride, a basic amine with an oxazolidinone/lactam, showed about 90% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Praziquantel, a lactam-containing drug, had F=27.2% even in patients with hepatic impairment, still above the 20% threshold and supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Didanosine, despite being a polar nucleoside, had an absolute oral bioavailability of 35±5% in humans, and most reported values are ≥20%, supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One didanosine pediatric record with an antacid solution reported F=19%, slightly below threshold; this is a formulation/pediatric outlier and is outweighed by the consistent high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer evidence, including structurally similar sulfonyl-piperazine fused lactams with F 34–73% and other lactam/basic-amine drugs with F 59–90%, consistently supports F≥20%; the only sub-20% values are pediatric/formulation outliers, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "Some records come from diseased, pediatric, or fed/fasted special populations, adding variability.",
    "The specific metabolic stability and transporter profile of the homopiperazine sulfonamide are not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C29", "C27", "C01", "C38", "C20", "C14", "C26", "C16", "C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "high-transfer oral bioavailability analogues"
    }
  ],
  "revision_action": "initial"
}

